def resolve(path, cwd, links):
    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    # Move to parent directory
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append the component to current path
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if candidate is a symlink
            if candidate in links:
                link_count += 1
                if link_count > max_links:
                    return None

                # Get the target of the symlink
                target = links[candidate]

                # Resolve relative symlink targets
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    # Target is relative to the directory containing the link
                    if candidate == '/':
                        current = '/'
                    else:
                        current = candidate.rsplit('/', 1)[0]
                    remaining = target

                # Continue resolution with the target
                break
            else:
                # Not a symlink, just update current
                current = candidate
        else:
            # All components processed without encountering a symlink
            break

    # Remove trailing slash except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

